// The baked layer's registry hook (BAKE stream; the runtime is model-kit.ts, the data is baked/<family>.ts, generated by scripts/bake/).
// Imported LAST by props/index.ts, after every category module (and after any other stream's module: soft2, dress-*), because a `replace`
// model overrides an already-registered type in place: Map.set on an existing key keeps its slot, so catalog order, propTypes() order and
// every per-instance seed (the Nth registry prop of a house draws the Nth stream) are exactly what they were. An `add` model registers a
// new type, appended after everything.
//
// Wave B1 is eager (statically imported, about 9 KB for the three pilots); a family that grows past the budget moves to a dynamic import()
// behind ensureBaked(types) (model-kit.ts), which every build call site already awaits.
//
// Switches: ?baked=0 (all off), ?baked=all (also the models still `enabled: false`, for review sheets), ?baked-off=<id,id>; see model-kit.ts.
import { PROPS } from './registry.js';
import { installBaked } from './model-kit.js';
import type { BakedModel } from './model-kit.js';
import { BAKED_BATH } from './baked/bath.js';
import { BAKED_BEDROOM } from './baked/bedroom.js';
import { BAKED_STORAGE } from './baked/storage.js';

/** Every baked model, in a fixed order (family by name, id by name within it). */
export const BAKED_MODELS: BakedModel[] = [BAKED_BATH, BAKED_BEDROOM, BAKED_STORAGE].flatMap(f => Object.values(f) as unknown as BakedModel[]);

installBaked(PROPS, BAKED_MODELS);
